// Build Briefing — validates API payloads, applies fallbacks, and renders a Telegram-safe HTML message.
// Runs once for all items; reads both sources by node name so it is independent of merge order.
const TZ = 'Asia/Jakarta';
const SCHEDULED_HOUR = 8;
const QUOTE_NODE = '[GET] Fetch Random Quote';
const WEATHER_NODE = "[GET] Fetch Jakarta's Weather";

const now = $now.setZone(TZ);
const today = now.toFormat('yyyy-MM-dd');
const isProduction = $execution.mode === 'production';
const warnings = [];

const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const isNum = (v) => typeof v === 'number' && Number.isFinite(v);
const clean = (s, max) => {
  let t = String(s).replace(/\s+/g, ' ').trim();
  if (t.length > max) t = t.slice(0, max - 1).trimEnd() + '…';
  return t;
};
const fmt = (n) => (Math.round(n * 10) / 10).toString();
const sourceJson = (name) => {
  try {
    const item = $(name).first();
    return item && item.json && typeof item.json === 'object' ? item.json : null;
  } catch (e) {
    return null;
  }
};

// ---------- Quote ----------
const FALLBACK_QUOTES = [
  { quote: 'Stay focused on progress, not perfection.', author: 'Unknown' },
  { quote: 'The secret of getting ahead is getting started.', author: 'Mark Twain' },
  { quote: 'Well done is better than well said.', author: 'Benjamin Franklin' },
  { quote: 'It always seems impossible until it is done.', author: 'Nelson Mandela' },
  { quote: 'Small deeds done are better than great deeds planned.', author: 'Peter Marshall' },
];
const q = sourceJson(QUOTE_NODE);
const qText = q && typeof q.quote === 'string' ? q.quote.trim() : '';
const qAuthor = q && typeof q.author === 'string' ? q.author.trim() : '';
let quote;
let author;
let quoteSource = 'api';
if (!q || q.error || qText.length < 3) {
  const fb = FALLBACK_QUOTES[now.ordinal % FALLBACK_QUOTES.length];
  quote = fb.quote;
  author = fb.author;
  quoteSource = 'fallback';
  warnings.push(!q ? 'quote_missing' : q.error ? 'quote_api_error' : 'quote_invalid_payload');
} else {
  quote = clean(qText, 500);
  author = qAuthor ? clean(qAuthor, 100) : 'Unknown';
}

// ---------- Weather (WMO weather codes) ----------
const WMO = {
  0: ['Clear sky', '☀️'], 1: ['Mainly clear', '🌤️'], 2: ['Partly cloudy', '⛅'], 3: ['Overcast', '☁️'],
  45: ['Fog', '🌫️'], 48: ['Rime fog', '🌫️'],
  51: ['Light drizzle', '🌦️'], 53: ['Drizzle', '🌦️'], 55: ['Heavy drizzle', '🌧️'],
  56: ['Freezing drizzle', '🌧️'], 57: ['Freezing drizzle', '🌧️'],
  61: ['Light rain', '🌦️'], 63: ['Rain', '🌧️'], 65: ['Heavy rain', '🌧️'],
  66: ['Freezing rain', '🌧️'], 67: ['Freezing rain', '🌧️'],
  71: ['Light snow', '🌨️'], 73: ['Snow', '🌨️'], 75: ['Heavy snow', '❄️'], 77: ['Snow grains', '🌨️'],
  80: ['Light showers', '🌦️'], 81: ['Showers', '🌧️'], 82: ['Violent showers', '⛈️'],
  85: ['Snow showers', '🌨️'], 86: ['Heavy snow showers', '🌨️'],
  95: ['Thunderstorm', '⛈️'], 96: ['Thunderstorm with hail', '⛈️'], 99: ['Thunderstorm with heavy hail', '⛈️'],
};
const describe = (code) => WMO[code] || ['Conditions unknown', '🌡️'];
const RAINY = new Set([51, 53, 55, 56, 57, 61, 63, 65, 66, 67, 80, 81, 82, 95, 96, 99]);

const w = sourceJson(WEATHER_NODE);
const cw = w && w.current_weather && typeof w.current_weather === 'object' ? w.current_weather : null;
const weatherLines = [];
let weatherSource = 'api';
let umbrella = false;

if (!w || w.error || !cw || !isNum(cw.temperature)) {
  weatherSource = 'unavailable';
  warnings.push(!w ? 'weather_missing' : w.error ? 'weather_api_error' : 'weather_invalid_payload');
  weatherLines.push('🌡️ <b>Weather:</b> data unavailable right now. Check a weather app before heading out.');
} else {
  const [label, icon] = describe(cw.weathercode);
  const t = cw.temperature;
  const feel = t >= 33 ? ' (very hot, stay hydrated)' : t >= 31 ? ' (hot)' : t < 24 ? ' (cool)' : '';
  const wind = isNum(cw.windspeed) ? `, wind ${fmt(cw.windspeed)} km/h` : '';
  weatherLines.push(`${icon} <b>Now:</b> ${fmt(t)}°C${feel}, ${esc(label)}${wind}`);
  if (RAINY.has(cw.weathercode)) umbrella = true;

  // Stale reading check (Open-Meteo returns local time when timezone param is set)
  if (typeof cw.time === 'string') {
    const obs = DateTime.fromISO(cw.time, { zone: TZ });
    if (obs.isValid && now.diff(obs, 'hours').hours > 3) {
      warnings.push('weather_stale');
      weatherLines.push(`<i>(reading from ${obs.toFormat('HH:mm')}, may be outdated)</i>`);
    }
  }

  const d = w.daily && typeof w.daily === 'object' ? w.daily : null;
  const idx = d && Array.isArray(d.time) ? d.time.indexOf(today) : -1;
  if (idx >= 0) {
    const tmin = d.temperature_2m_min?.[idx];
    const tmax = d.temperature_2m_max?.[idx];
    const pop = d.precipitation_probability_max?.[idx];
    const dcode = d.weathercode?.[idx] ?? d.weather_code?.[idx];
    const parts = [];
    if (isNum(tmin) && isNum(tmax)) parts.push(`${fmt(tmin)}–${fmt(tmax)}°C`);
    if (isNum(dcode)) parts.push(esc(describe(dcode)[0]).toLowerCase());
    if (isNum(pop)) parts.push(`rain chance ${Math.round(pop)}%`);
    if (parts.length) weatherLines.push(`📅 <b>Today:</b> ${parts.join(', ')}`);
    if ((isNum(pop) && pop >= 60) || (isNum(dcode) && RAINY.has(dcode))) umbrella = true;
  } else {
    warnings.push('weather_daily_missing');
  }
  if (umbrella) weatherLines.push('☔ Bring an umbrella.');
}

// ---------- Compose ----------
const isWeekend = now.weekday >= 6;
const isLate = isProduction && now.hour > SCHEDULED_HOUR;
const dateLabel = now.toFormat('cccc, d LLLL yyyy');
const header = isWeekend
  ? `🌴 <b>WEEKEND BRIEFING</b>\n${dateLabel}`
  : `☀️ <b>MORNING BRIEFING</b>\n${dateLabel}`;

const blocks = [header];
if (isLate) blocks.push(`<i>⏰ Sent late at ${now.toFormat('HH:mm')} (scheduled ${String(SCHEDULED_HOUR).padStart(2, '0')}:00). The system was unavailable earlier.</i>`);
blocks.push(weatherLines.join('\n'));
blocks.push(`💬 <i>"${esc(quote)}"</i>\n— ${esc(author)}`);
if (quoteSource === 'fallback' || weatherSource !== 'api') blocks.push('<i>ℹ️ Some data sources were unavailable; fallback content was used.</i>');

let text = blocks.join('\n\n');
if (text.length > 4000) text = text.slice(0, 3990) + '…'; // Telegram limit is 4096

return [{
  json: {
    text,
    date: today,
    mode: isProduction ? 'production' : 'manual',
    quote_source: quoteSource,
    weather_source: weatherSource,
    is_late: isLate,
    warnings: warnings.join(','),
  },
}];
